def checked_rows(self):
    """
    A generator which yields rows which are ready to write to output.
    """
    length = len(self.column_names)
    line_number = self.reader.line_num
    joinable_row_errors = []

    for row in self.reader:
        try:
            if len(row) != length:
                raise LengthMismatchError(line_number, row, length)

            yield row

            # Don't join rows across valid rows.
            joinable_row_errors = []
        except LengthMismatchError as e:
            self.errors.append(e)

            # Don't join with long rows.
            if len(row) > length:
                joinable_row_errors = []
            else:
                joinable_row_errors.append(e)

                while joinable_row_errors:
                    fixed_row = join_rows([error.row for error in joinable_row_errors], joiner=' ')

                    if len(fixed_row) < length:
                        break

                    if len(fixed_row) == length:
                        self.rows_joined += len(joinable_row_errors)
                        self.joins += 1

                        yield fixed_row

                        for fixed in joinable_row_errors:
                            joinable_row_errors.remove(fixed)
                            self.errors.remove(fixed)

                        break

                    # keep trying in case we're too long because of a straggler
                    joinable_row_errors = joinable_row_errors[1:]

        except CSVTestException as e:
            self.errors.append(e)

            # Don't join rows across other errors.
            joinable_row_errors = []

        line_number = self.reader.line_num

class RowChecker:
    """
    Iterate over rows of a CSV producing cleaned rows and storing error rows.
    """

    def __init__(self, reader):
        self.reader = reader
        try:
            self.column_names = next(reader)
        except StopIteration:
            self.column_names = []
        self.errors = []
        self.rows_joined = 0
        self.joins = 0

    def checked_rows(self):
        """
        A generator which yields rows which are ready to write to output.
        """
        length = len(self.column_names)
        line_number = self.reader.line_num
        joinable_row_errors = []

        for row in self.reader:
            try:
                if len(row) != length:
                    raise LengthMismatchError(line_number, row, length)

                yield row

                # Don't join rows across valid rows.
                joinable_row_errors = []
            except LengthMismatchError as e:
                self.errors.append(e)

                # Don't join with long rows.
                if len(row) > length:
                    joinable_row_errors = []
                else:
                    joinable_row_errors.append(e)

                    while joinable_row_errors:
                        fixed_row = join_rows([error.row for error in joinable_row_errors], joiner=' ')

                        if len(fixed_row) < length:
                            break

                        if len(fixed_row) == length:
                            self.rows_joined += len(joinable_row_errors)
                            self.joins += 1

                            yield fixed_row

                            for fixed in joinable_row_errors:
                                joinable_row_errors.remove(fixed)
                                self.errors.remove(fixed)

                            break

                        # keep trying in case we're too long because of a straggler
                        joinable_row_errors = joinable_row_errors[1:]

            except CSVTestException as e:
                self.errors.append(e)

                # Don't join rows across other errors.
                joinable_row_errors = []

            line_number = self.reader.line_num

class LengthMismatchError(CSVTestException):
    """
    Encapsulate information about a row which as the wrong length.
    """

    def __init__(self, line_number, row, expected_length):
        msg = 'Expected %i columns, found %i columns' % (expected_length, len(row))
        super().__init__(line_number, row, msg)

    @property
    def length(self):
        return len(self.row)

def main(self):
    if self.additional_input_expected():
        sys.stderr.write('No input file or piped data provided. Waiting for standard input:\n')

    reader = agate.csv.reader(self.skip_lines(), **self.reader_kwargs)

    if self.args.dryrun:
        checker = RowChecker(reader)

        for _row in checker.checked_rows():
            pass

        if checker.errors:
            for e in checker.errors:
                self.output_file.write('Line %i: %s\n' % (e.line_number, e.msg))
        else:
            self.output_file.write('No errors.\n')

        if checker.joins:
            self.output_file.write('%i rows would have been joined/reduced to %i rows after eliminating expected '
                                   'internal line breaks.\n' % (checker.rows_joined, checker.joins))
    else:
        if self.input_file == sys.stdin:
            base = 'stdin'  # "<stdin>_out.csv" is invalid on Windows
        else:
            base = splitext(self.input_file.name)[0]

        with open(f'{base}_out.csv', 'w') as f:
            clean_writer = agate.csv.writer(f, **self.writer_kwargs)

            checker = RowChecker(reader)
            clean_writer.writerow(checker.column_names)

            for row in checker.checked_rows():
                clean_writer.writerow(row)

        if checker.errors:
            error_filename = f'{base}_err.csv'

            with open(error_filename, 'w') as f:
                error_writer = agate.csv.writer(f, **self.writer_kwargs)

                error_header = ['line_number', 'msg']
                error_header.extend(checker.column_names)
                error_writer.writerow(error_header)

                error_count = len(checker.errors)

                for e in checker.errors:
                    error_writer.writerow(self._format_error_row(e))

            self.output_file.write('%i error%s logged to %s\n' % (
                error_count, '' if error_count == 1 else 's', error_filename))
        else:
            self.output_file.write('No errors.\n')

        if checker.joins:
            self.output_file.write('%i rows were joined/reduced to %i rows after eliminating expected internal '
                                   'line breaks.\n' % (checker.rows_joined, checker.joins))

class CSVClean(CSVKitUtility):
    description = 'Fix common errors in a CSV file.'
    override_flags = ['L', 'blanks', 'date-format', 'datetime-format']

    def add_arguments(self):
        self.argparser.add_argument(
            '-n', '--dry-run', dest='dryrun', action='store_true',
            help='Do not create output files. Information about what would have been done will be printed to STDERR.')

    def main(self):
        if self.additional_input_expected():
            sys.stderr.write('No input file or piped data provided. Waiting for standard input:\n')

        reader = agate.csv.reader(self.skip_lines(), **self.reader_kwargs)

        if self.args.dryrun:
            checker = RowChecker(reader)

            for _row in checker.checked_rows():
                pass

            if checker.errors:
                for e in checker.errors:
                    self.output_file.write('Line %i: %s\n' % (e.line_number, e.msg))
            else:
                self.output_file.write('No errors.\n')

            if checker.joins:
                self.output_file.write('%i rows would have been joined/reduced to %i rows after eliminating expected '
                                       'internal line breaks.\n' % (checker.rows_joined, checker.joins))
        else:
            if self.input_file == sys.stdin:
                base = 'stdin'  # "<stdin>_out.csv" is invalid on Windows
            else:
                base = splitext(self.input_file.name)[0]

            with open(f'{base}_out.csv', 'w') as f:
                clean_writer = agate.csv.writer(f, **self.writer_kwargs)

                checker = RowChecker(reader)
                clean_writer.writerow(checker.column_names)

                for row in checker.checked_rows():
                    clean_writer.writerow(row)

            if checker.errors:
                error_filename = f'{base}_err.csv'

                with open(error_filename, 'w') as f:
                    error_writer = agate.csv.writer(f, **self.writer_kwargs)

                    error_header = ['line_number', 'msg']
                    error_header.extend(checker.column_names)
                    error_writer.writerow(error_header)

                    error_count = len(checker.errors)

                    for e in checker.errors:
                        error_writer.writerow(self._format_error_row(e))

                self.output_file.write('%i error%s logged to %s\n' % (
                    error_count, '' if error_count == 1 else 's', error_filename))
            else:
                self.output_file.write('No errors.\n')

            if checker.joins:
                self.output_file.write('%i rows were joined/reduced to %i rows after eliminating expected internal '
                                       'line breaks.\n' % (checker.rows_joined, checker.joins))

    def _format_error_row(self, error):
        row = [error.line_number, error.msg]
        row.extend(error.row)

        return row

def get_rows_and_column_names_and_column_ids(self, **kwargs):
    rows = agate.csv.reader(self.skip_lines(), **kwargs)

    try:
        next_row = next(rows)
    except StopIteration:
        return iter([]), [], []

    if self.args.no_header_row:
        # Peek at a row to get the number of columns.
        row = next_row
        rows = itertools.chain([row], rows)
        column_names = make_default_headers(len(row))
    else:
        column_names = next_row

    column_offset = self.get_column_offset()
    if kwargs.get('line_numbers'):
        column_offset -= 1

    column_ids = parse_column_identifiers(
        self.args.columns,
        column_names,
        column_offset,
        getattr(self.args, 'not_columns', None),
    )

    return rows, column_names, column_ids

def test_row(self, row):
    for idx, test in self.patterns.items():
        try:
            value = row[idx]
        except IndexError:
            value = ''
        result = test(value)
        if self.any_match:
            if result:
                return not self.inverse  # True
        else:
            if not result:
                return self.inverse  # False

    if self.any_match:
        return self.inverse  # False
    return not self.inverse  # True
